*/
'use strict';

var proofPacking = require('@zk-kit/utils/proof-packing');
var constants = require('@semaphore-protocol/utils/constants');
var artifacts = require('@zk-kit/artifacts');
var errorHandlers = require('@zk-kit/utils/error-handlers');
var snarkjs = require('snarkjs');
var crypto = require('ethers/crypto');
var utils = require('ethers/utils');
var abi = require('ethers/abi');

/**
 * Creates a keccak256 hash of a message compatible with the SNARK scalar modulus.
 * @param message The message to be hashed.
 * @returns The message digest.
 */
function hash(message) {
    return (BigInt(crypto.keccak256(utils.toBeHex(message, 32))) >> 8n).toString();
}

/**
 * Converts a bignumberish or a text to a bigint.
 * @param value The value to be converted to bigint.
 * @return The value converted to bigint.
 */
function toBigInt(value) {
    try {
        return utils.toBigInt(value);
    }
    catch (error) {
        if (typeof value === "string") {
            return utils.toBigInt(abi.encodeBytes32String(value));
        }
        throw TypeError(error instanceof Error ? error.message : error.toString());
    }
}

/**
 * It generates a Semaphore proof, i.e. a zero-knowledge proof that an identity that
 * is part of a group has shared an anonymous message.
 * The message may be any arbitrary user-defined value (e.g. a vote), or the hash of that value.
